/**
 * config.toml for the Open Interpreter engine, generated by Afuufow into its own private INTERPRETER_HOME
 * (never the owner's own ~/.openinterpreter). Secrets are NOT written here: API keys are passed as environment
 * variables of the engine process only.
 */

export interface EngineConfigInput {
  /** Built-in provider id ("anthropic", "openai", "google", ...) or a custom one described by `custom`. */
  provider: string;
  model: string;
  /** The folder the engine works in. It is marked "untrusted" so the engine itself asks before running ANY command. */
  cwd: string;
  webSearch: boolean;
  /** Optional MCP browser server (Playwright). */
  browser?: { command: string; args: string[] } | null;
  /** For tests / OpenAI-compatible gateways. */
  custom?: { id: string; name: string; baseUrl: string; envKey: string; wireApi: 'chat' | 'responses' } | null;
}

/** TOML literal string ('...'): backslashes in Windows paths need no escaping. A single quote cannot occur in the values we pass. */
const lit = (s: string) => {
  if (/[\r\n']/.test(s)) throw new Error('unsupported character in config value');
  return `'${s}'`;
};
const basic = (s: string) => `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, ' ')}"`;

export function buildEngineConfig(c: EngineConfigInput): string {
  const lines: string[] = [
    '# Generated by Afuufow. Edits are overwritten on the next task.',
    `model_provider = ${basic(c.custom?.id ?? c.provider)}`,
    `model = ${basic(c.model)}`,
    'sandbox_mode = "workspace-write"',
    `web_search = ${c.webSearch ? '"live"' : '"disabled"'}`,
    'check_for_update_on_startup = false',
    '',
    `[projects.${lit(c.cwd)}]`,
    'trust_level = "untrusted"',
    '',
    '[features]',
    'plugins = false',
    'apps = false',
    'memories = false',
    'undo = false',
    'multi_agent = false',
  ];
  if (c.custom) {
    lines.push('', `[model_providers.${c.custom.id}]`, `name = ${basic(c.custom.name)}`, `base_url = ${basic(c.custom.baseUrl)}`, `env_key = ${basic(c.custom.envKey)}`, `wire_api = ${basic(c.custom.wireApi)}`);
  }
  if (c.browser) {
    lines.push('', '[mcp_servers.browser]', `command = ${basic(c.browser.command)}`, `args = [${c.browser.args.map(basic).join(', ')}]`, 'default_tools_approval_mode = "prompt"');
  }
  return lines.join('\n') + '\n';
}
